import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Resource tracking for cleanup
  const materials = [];
  const geometries = [];
  const textures = [];

  // Load background texture
  let bgTexture = null;
  if (config.imageUrl) {
    bgTexture = ctx.textureLoader.load(config.imageUrl);
    bgTexture.colorSpace = THREE.SRGBColorSpace;
    textures.push(bgTexture);
  }

  // Create background plane
  const planeGeom = new THREE.PlaneGeometry(1, 1);
  geometries.push(planeGeom);

  const planeMat = new THREE.MeshBasicMaterial({
    map: bgTexture,
    side: THREE.DoubleSide,
  });
  materials.push(planeMat);

  const planeMesh = new THREE.Mesh(planeGeom, planeMat);

  // Apply scale if specified
  if (config.scenePosition?.scaleXYZ) {
    planeMesh.scale.set(...config.scenePosition.scaleXYZ);
  }

  group.add(planeMesh);

  // Add text content via fontAtlas
  if (config.textContent && ctx.fontAtlas) {
    const textMesh = ctx.fontAtlas.createTextMesh(
      config.textContent,
      {
        fontSize: 0.34,
        fontFamily: 'Lora',
        fontWeight: 400,
        color: new THREE.Color(config.colors?.ink || '#16161d'),
        align: 'center',
      }
    );

    if (textMesh) {
      textMesh.position.z = 0.01;
      group.add(textMesh);
    }
  }

  // Apply position and rotation from scenePosition
  if (config.scenePosition) {
    const pos = config.scenePosition;
    group.position.set(
      pos.x || 0,
      pos.y || 0,
      pos.z || 0
    );
    if (pos.rotationXYZ) {
      group.rotation.set(
        pos.rotationXYZ[0] || 0,
        pos.rotationXYZ[1] || 0,
        pos.rotationXYZ[2] || 0
      );
    }
  }

  // Cleanup function to dispose resources
  group.userData.cleanup = () => {
    materials.forEach(mat => mat.dispose());
    geometries.forEach(geo => geo.dispose());
    textures.forEach(tex => tex.dispose());
  };

  // Event handlers (empty for static element)
  group.userData.handlers = {};

  return group;
}
